// Parse request and extract routing information
const input = $input.first().json;
const headers = input.headers || {};
const path = input.params?.['*'] || '';
const method = input.method || 'GET';

// Extract API key from header or query
const apiKey = headers['x-api-key'] || headers['authorization']?.replace('Bearer ', '') || input.query?.api_key;

// Parse path segments
const segments = path.split('/').filter(s => s);
const resource = segments[0] || 'root';
const resourceId = segments[1] || null;
const subResource = segments[2] || null;

// Request context
const request = {
  id: `req_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
  timestamp: new Date().toISOString(),
  method,
  path: `/api/v1/${path}`,
  resource,
  resourceId,
  subResource,
  segments,
  apiKey,
  clientIp: headers['x-forwarded-for'] || headers['x-real-ip'] || 'unknown',
  userAgent: headers['user-agent'] || 'unknown',
  body: input.body || {},
  query: input.query || {},
  headers
};

return [{ json: request }];

// Authenticate request
const request = $input.first().json;
const staticData = $workflow.staticData;

// Initialize API keys (in production, load from database)
if (!staticData.apiKeys) {
  staticData.apiKeys = {
    'test-key-123': { name: 'Test App', permissions: ['read', 'write'], rateLimit: 100 },
    'admin-key-456': { name: 'Admin App', permissions: ['read', 'write', 'admin'], rateLimit: 1000 }
  };
}

const apiKey = request.apiKey;
const keyData = staticData.apiKeys[apiKey];

if (!apiKey) {
  return [{
    json: {
      ...request,
      authenticated: false,
      error: { code: 401, message: 'Missing API key. Provide X-API-Key header.' }
    }
  }];
}

if (!keyData) {
  return [{
    json: {
      ...request,
      authenticated: false,
      error: { code: 401, message: 'Invalid API key.' }
    }
  }];
}

return [{
  json: {
    ...request,
    authenticated: true,
    client: keyData.name,
    permissions: keyData.permissions,
    rateLimit: keyData.rateLimit
  }
}];

// Rate limiting check
const request = $input.first().json;
const staticData = $workflow.staticData;

// Initialize rate limit tracking
if (!staticData.rateLimits) {
  staticData.rateLimits = {};
}

const clientKey = request.apiKey;
const now = Date.now();
const windowMs = 60000; // 1 minute window

// Clean old entries
if (!staticData.rateLimits[clientKey]) {
  staticData.rateLimits[clientKey] = [];
}
staticData.rateLimits[clientKey] = staticData.rateLimits[clientKey].filter(
  t => now - t < windowMs
);

// Check rate limit
const currentCount = staticData.rateLimits[clientKey].length;
const limit = request.rateLimit || 100;

if (currentCount >= limit) {
  const resetTime = Math.ceil((staticData.rateLimits[clientKey][0] + windowMs - now) / 1000);
  return [{
    json: {
      ...request,
      rateLimited: true,
      error: {
        code: 429,
        message: 'Rate limit exceeded',
        retryAfter: resetTime
      }
    }
  }];
}

// Record this request
staticData.rateLimits[clientKey].push(now);

return [{
  json: {
    ...request,
    rateLimited: false,
    rateInfo: {
      remaining: limit - currentCount - 1,
      limit,
      reset: new Date(now + windowMs).toISOString()
    }
  }
}];

// Validate request body against schema
const request = $input.first().json;

// Schema definitions per resource/method
const schemas = {
  users: {
    POST: {
      required: ['email', 'name'],
      properties: {
        email: { type: 'string', pattern: '^[^@]+@[^@]+$' },
        name: { type: 'string', minLength: 1 },
        role: { type: 'string', enum: ['user', 'admin'] }
      }
    },
    PUT: {
      properties: {
        email: { type: 'string', pattern: '^[^@]+@[^@]+$' },
        name: { type: 'string', minLength: 1 }
      }
    }
  },
  orders: {
    POST: {
      required: ['items', 'customerId'],
      properties: {
        customerId: { type: 'string' },
        items: { type: 'array', minItems: 1 }
      }
    }
  }
};

const schema = schemas[request.resource]?.[request.method];
const body = request.body;
const errors = [];

if (schema) {
  // Check required fields
  if (schema.required) {
    for (const field of schema.required) {
      if (body[field] === undefined || body[field] === null) {
        errors.push(`Missing required field: ${field}`);
      }
    }
  }

  // Validate properties
  if (schema.properties && errors.length === 0) {
    for (const [field, rules] of Object.entries(schema.properties)) {
      const value = body[field];
      if (value !== undefined) {
        if (rules.type === 'string' && typeof value !== 'string') {
          errors.push(`Field ${field} must be a string`);
        }
        if (rules.type === 'array' && !Array.isArray(value)) {
          errors.push(`Field ${field} must be an array`);
        }
        if (rules.minLength && value.length < rules.minLength) {
          errors.push(`Field ${field} must be at least ${rules.minLength} characters`);
        }
        if (rules.enum && !rules.enum.includes(value)) {
          errors.push(`Field ${field} must be one of: ${rules.enum.join(', ')}`);
        }
        if (rules.pattern && !new RegExp(rules.pattern).test(value)) {
          errors.push(`Field ${field} has invalid format`);
        }
      }
    }
  }
}

if (errors.length > 0) {
  return [{
    json: {
      ...request,
      valid: false,
      error: { code: 400, message: 'Validation failed', details: errors }
    }
  }];
}

return [{ json: { ...request, valid: true } }];

// Check cache for GET requests
const request = $input.first().json;
const staticData = $workflow.staticData;

// Only cache GET requests
if (request.method !== 'GET') {
  return [{ json: { ...request, cached: false, cacheHit: false } }];
}

// Initialize cache
if (!staticData.cache) {
  staticData.cache = {};
}

// Generate cache key
const cacheKey = `${request.resource}:${request.resourceId || 'list'}:${JSON.stringify(request.query)}`;
const cached = staticData.cache[cacheKey];
const now = Date.now();

// Check if cache is valid (5 minute TTL)
if (cached && now - cached.timestamp < 300000) {
  return [{
    json: {
      ...request,
      cached: true,
      cacheHit: true,
      cacheKey,
      cachedResponse: cached.data
    }
  }];
}

return [{ json: { ...request, cached: false, cacheHit: false, cacheKey } }];

// Handle /users endpoint
const request = $input.first().json;

// Simulated user data (replace with actual database/API calls)
const users = [
  { id: '1', email: 'alice@example.com', name: 'Alice', role: 'admin' },
  { id: '2', email: 'bob@example.com', name: 'Bob', role: 'user' },
  { id: '3', email: 'charlie@example.com', name: 'Charlie', role: 'user' }
];

let response;

switch (request.method) {
  case 'GET':
    if (request.resourceId) {
      const user = users.find(u => u.id === request.resourceId);
      response = user || { error: 'User not found' };
    } else {
      response = { users, total: users.length };
    }
    break;
  case 'POST':
    response = {
      id: String(Date.now()),
      ...request.body,
      createdAt: new Date().toISOString()
    };
    break;
  case 'PUT':
    response = {
      id: request.resourceId,
      ...request.body,
      updatedAt: new Date().toISOString()
    };
    break;
  case 'DELETE':
    response = { deleted: true, id: request.resourceId };
    break;
  default:
    response = { error: 'Method not allowed' };
}

return [{ json: { request, response, resource: 'users' } }];

// Handle /orders endpoint
const request = $input.first().json;

// Simulated order data
const orders = [
  { id: 'ord-1', customerId: '1', items: [{sku: 'A1', qty: 2}], status: 'completed' },
  { id: 'ord-2', customerId: '2', items: [{sku: 'B2', qty: 1}], status: 'pending' }
];

let response;

switch (request.method) {
  case 'GET':
    if (request.resourceId) {
      const order = orders.find(o => o.id === request.resourceId);
      response = order || { error: 'Order not found' };
    } else {
      response = { orders, total: orders.length };
    }
    break;
  case 'POST':
    response = {
      id: `ord-${Date.now()}`,
      ...request.body,
      status: 'pending',
      createdAt: new Date().toISOString()
    };
    break;
  default:
    response = { error: 'Method not allowed' };
}

return [{ json: { request, response, resource: 'orders' } }];

// Handle /products endpoint
const request = $input.first().json;

// Simulated product data
const products = [
  { id: 'prod-1', name: 'Widget A', price: 29.99, stock: 100 },
  { id: 'prod-2', name: 'Widget B', price: 49.99, stock: 50 },
  { id: 'prod-3', name: 'Widget C', price: 99.99, stock: 25 }
];

let response;

switch (request.method) {
  case 'GET':
    if (request.resourceId) {
      const product = products.find(p => p.id === request.resourceId);
      response = product || { error: 'Product not found' };
    } else {
      response = { products, total: products.length };
    }
    break;
  default:
    response = { error: 'Method not allowed' };
}

return [{ json: { request, response, resource: 'products' } }];

// Handle unknown resource
const request = $input.first().json;

return [{
  json: {
    request,
    response: {
      error: 'Resource not found',
      availableResources: ['users', 'orders', 'products']
    },
    resource: 'unknown'
  }
}];

// Update cache for successful responses
const result = $input.first().json;
const staticData = $workflow.staticData;

if (!staticData.cache) {
  staticData.cache = {};
}

// Cache successful GET responses
if (result.request.method === 'GET' && !result.response.error) {
  const cacheKey = result.request.cacheKey;
  if (cacheKey) {
    staticData.cache[cacheKey] = {
      data: result.response,
      timestamp: Date.now()
    };
  }
}

return [{ json: result }];

// Format final response
const input = $input.first().json;

let statusCode = 200;
let response;

// Check for cached response
if (input.cachedResponse) {
  response = {
    data: input.cachedResponse,
    meta: {
      cached: true,
      requestId: input.id
    }
  };
} else if (input.response) {
  // Normal response
  if (input.response.error) {
    statusCode = input.response.error === 'Resource not found' ? 404 : 
                 input.response.error === 'Method not allowed' ? 405 : 400;
  }
  response = {
    data: input.response,
    meta: {
      cached: false,
      requestId: input.request?.id || input.id,
      resource: input.resource
    }
  };
} else {
  // Error response
  statusCode = input.error?.code || 500;
  response = {
    error: input.error || { message: 'Internal server error' },
    meta: {
      requestId: input.id
    }
  };
}

// Add rate limit headers info
if (input.rateInfo) {
  response.meta = response.meta || {};
  response.meta.rateLimit = input.rateInfo;
}

return [{
  json: {
    statusCode,
    response,
    headers: {
      'X-Request-ID': input.request?.id || input.id,
      'X-RateLimit-Remaining': input.rateInfo?.remaining?.toString() || 'N/A'
    }
  }
}];
